"""The 5M model: ft3's CausalPatchDecoder with tidemark's loss mask (tideforge/model/ft3_model.py, generated by
tools/port_model.py), built from the recipe's cfg.

build(cfg, options) is the model-option hook for later model changes (EXPERIMENTS.md: M1 known-covariate attention over the whole
window, M2 static embedding, M3 more lanes). Every option is "off" in the T3 recipe; any other value raises until that change
exists, so a config cannot silently ask for an unbuilt model.
"""
from __future__ import annotations

from tideforge.model import ft3_model as FM

OPTIONS = {"known_attn": "off"}          # M1 (owner 2026-10-29: hook only in T3)


def build(cfg: dict, options: dict | None = None):
    opts = dict(OPTIONS, **(options or {}))
    bad = sorted(set(opts) - set(OPTIONS))
    if bad:
        raise KeyError(f"unknown model option(s) {bad}; known: {sorted(OPTIONS)}")
    for k, v in opts.items():
        if v != "off":
            raise NotImplementedError(f"model option {k}={v!r} is not built yet (only 'off')")
    return FM.build_masked_model(cfg)


def n_params(model) -> int:
    return sum(p.numel() for p in model.parameters())
